//---------------------------------------------------------------
// Based on:
//
// Analytic Normals 3D
// https://www.shadertoy.com/view/XttSz2
// (The MIT License)
//
// Analytic Normals - article:
// https://iquilezles.org/articles/morenoise/
//---------------------------------------------------------------

//---------------------------------------------------------------
float hash(float n) { return fract(sin(n)*753.5453123); }

//---------------------------------------------------------------
// value noise
//---------------------------------------------------------------
float sdFbm4_noised(in vec3 x)
{
    vec3 p = floor(x);
    vec3 w = fract(x);
	vec3 u = w*w*(3.0-2.0*w);

    float n = p.x + p.y*157.0 + 113.0*p.z;

    float a = hash(n+  0.0);
    float b = hash(n+  1.0);
    float c = hash(n+157.0);
    float d = hash(n+158.0);
    float e = hash(n+113.0);
	float f = hash(n+114.0);
    float g = hash(n+270.0);
    float h = hash(n+271.0);

    float k0 =   a;
    float k1 =   b - a;
    float k2 =   c - a;
    float k3 =   e - a;
    float k4 =   a - b - c + d;
    float k5 =   a - c - e + g;
    float k6 =   a - b - e + f;
    float k7 = - a + b + c - d + e - f - g + h;

    return k0 + k1*u.x + k2*u.y + k3*u.z + k4*u.x*u.y + k5*u.y*u.z + k6*u.z*u.x + k7*u.x*u.y*u.z;
}

float sdFbm4_fbmd(in vec3 x, in float scale)
{
    float a = 0.0;
    float b = 0.5;
	float f = 1.0;
    vec3  d = vec3(0.0);
    for( int i=0; i<4; i++ )
    {
        float n = sdFbm4_noised(f*x*scale);
        a += b*n;             // accumulate values		
        b *= 0.5;             // amplitude decrease
        f *= 1.8;             // frequency increase
    }

	return a;
}

float sdFbm4(vec3 p, float fbmScale, float fbmValOffset, float fbmValMul)
{
	float d1 = sdFbm4_fbmd(p, fbmScale);
    d1 += fbmValOffset * 0.1;
	d1 *= fbmValMul * 0.1;

    return d1;
}
